export type SignatureFactoryResult = {
  signature: string;
  timestamp: number;
  nonce: number | string;
};

export interface IMClient {
  on(event: string, listener: (...args: unknown[]) => void): void;
  close(): Promise<void>;
  createConversation(options: {
    members: string[];
    name?: string;
    unique?: boolean;
    transient?: boolean;
  }): Promise<Conversation>;
  getConversation(conversationId: string): Promise<Conversation | null>;
}

export interface Conversation {
  id: string;
  name?: string;
  members: string[];
  send<TMessage extends TypedMessage | Record<string, unknown>>(
    message: TMessage,
    options?: {
      transient?: boolean;
    }
  ): Promise<TMessage & { id: string; timestamp: number }>;
  recall(messageId: string): Promise<void>;
}

export class Realtime {
  constructor(options: {
    appId: string;
    appKey: string;
    server?: string;
    plugins?: unknown[];
  });
  register(messageClass: typeof TypedMessage): void;
  createIMClient(
    clientId: string,
    options?: {
      signatureFactory?: () => Promise<SignatureFactoryResult>;
    }
  ): Promise<IMClient>;
}

export class TypedMessage {
  id?: string;
  timestamp?: number;
  constructor();
}

export const TypedMessagesPlugin: Record<string, unknown>;
export const debug:
  | {
      enable?: () => void;
      disable?: () => void;
    }
  | undefined;

export function setAdapters(adapters: Record<string, unknown>): void;
export function messageType(type: number): (klass: typeof TypedMessage) => void;
export function messageField(fields: string[]): (klass: typeof TypedMessage) => void;
